function editPresentationGeometry(node,key,value){const number=Number(value);if(!Number.isFinite(number))return renderProperties();const before={x:node.x,y:node.y,width:node.width,height:node.height};if(before[key]===number)return;checkpoint();node[key]=number;const diagram=activeDiagram();if(node.boundary&&['x','y'].includes(key))snapBoundary(node,diagram);const operation=['x','y'].includes(key)?{type:'move-node',diagramId:diagram.id,nodeId:node.id,x:node.x,y:node.y,expectedValue:{x:before.x,y:before.y}}:{type:'resize-node',diagramId:diagram.id,nodeId:node.id,width:node.width,height:node.height,expectedValue:{width:before.width,height:before.height}};commitLocal(operation,`Updated presentation ${key}`)}
