function visibleCompartmentItems(e,name){const kinds=COMPARTMENT_DEFINITIONS[name]?.kinds||[];if(name==='providedInterfaces')return (e.providedInterfaceIds||[]).map(id=>findElement(project,id)).filter(Boolean);if(name==='requiredInterfaces')return (e.requiredInterfaceIds||[]).map(id=>findElement(project,id)).filter(Boolean);return project.elements.filter(x=>x.ownerId===e.id&&kinds.includes(x.kind))}
function addOwnedFeature(owner,kind){checkpoint();const feature=defaultElement(kind,owner.id);feature.name=kind.replace(/Property$/,'').replace(/([a-z])([A-Z])/g,'$1 $2').toLowerCase();project.elements.push(feature);const d=activeDiagram();let node=null;if(d&&d.contextId===owner.id&&allowed(d.diagramType).elements.includes(kind)){node={id:uid('node'),elementId:feature.id,x:owner.kind==='Block'?80:120,y:80,width:widthFor(kind),height:heightFor(kind),rotation:0};if(['ProxyPort','FullPort'].includes(kind))Object.assign(node,{width:18,height:18,boundary:true});d.nodes.push(node)}selected={type:'element',id:feature.id,nodeId:node?.id||null,edgeId:null};commitLocal({type:'create-element',element:structuredClone(feature),diagramId:d?.id,node:node?structuredClone(node):null},`Created ${kind} in ${owner.name}`)}
function section(title,children=[]){const s=document.createElement('div');s.className='section';s.innerHTML=`<h3>${title}</h3>`;for(const c of children)s.append(c);return s}function field(label,value,onchange,event='input',area=false){const r=document.createElement('label');r.className='field';r.innerHTML=`<span>${label}</span>`;const i=document.createElement(area?'textarea':'input');i.value=value??'';if(!onchange)i.readOnly=true;else i.addEventListener(event,e=>onchange(e.target.value));r.append(i);return r}function dateField(label,value,onchange){const r=field(label,String(value||'').slice(0,10),onchange,'change');r.querySelector('input').type='date';return r}function selectField(label,value,opts,onchange){const r=document.createElement('label');r.className='field';r.innerHTML=`<span>${label}</span>`;const s=document.createElement('select');const blank=document.createElement('option');blank.value='';blank.textContent='—';s.append(blank);for(const [v,n] of opts){const o=document.createElement('option');o.value=v;o.textContent=n;s.append(o)}s.value=value||'';s.onchange=e=>onchange(e.target.value);r.append(s);return r}function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b}
function createOrOpenChild(e){let type=e.kind==='Block'?'Internal Block Diagram':e.kind==='Activity'?'Activity Diagram':e.kind==='StateMachine'?'State Machine Diagram':e.kind==='Interaction'?'Sequence Diagram':null;if(!type){log('This element type does not own a child diagram.','warn');return}let d=project.diagrams.find(x=>x.contextId===e.id&&x.diagramType===type);if(!d){checkpoint();d={id:uid('diagram'),externalId:uid('DGM').toUpperCase(),name:`${e.name} ${DIAGRAMS[type].abbreviation}`,diagramType:type,ownerId:e.ownerId,contextId:e.id,nodes:[],edges:[],documentation:''};project.diagrams.push(d);normalizeIBDProject(project);commitLocal({type:'create-diagram',diagram:structuredClone(d)},`Created ${type}`)}project.activeDiagramId=d.id;render()}
