function isEditingTarget(target){return target?.matches?.('input,textarea,select,[contenteditable="true"]')}
let typingAwarenessTimer=null;document.addEventListener('focusin',event=>{if(!isEditingTarget(event.target))return;const propertyName=event.target.closest('.field')?.querySelector('span')?.textContent||event.target.dataset.field||event.target.name||'property';publishCurrentAwareness({propertyName,typing:false})});document.addEventListener('input',event=>{if(!isEditingTarget(event.target))return;const propertyName=event.target.closest('.field')?.querySelector('span')?.textContent||event.target.dataset.field||event.target.name||'property';publishCurrentAwareness({propertyName,typing:true});clearTimeout(typingAwarenessTimer);typingAwarenessTimer=setTimeout(()=>publishCurrentAwareness({propertyName,typing:false}),900)});document.addEventListener('focusout',event=>{if(isEditingTarget(event.target))publishCurrentAwareness({propertyName:null,typing:false})});document.addEventListener('pointerup',()=>publishCurrentAwareness());
function viewportDiagramCenter(){const wrap=$('canvasWrap'),rect=$('canvas').getBoundingClientRect();return diagramPointFromClient({clientX:wrap.getBoundingClientRect().left+wrap.clientWidth/2,clientY:wrap.getBoundingClientRect().top+wrap.clientHeight/2},rect,zoom)}
function revealPresentation(node){const wrap=$('canvasWrap');wrap.scrollTo({left:(node.x+node.width/2)*zoom-wrap.clientWidth/2,top:(node.y+node.height/2)*zoom-wrap.clientHeight/2,behavior:'smooth'});selected={type:'element',id:node.elementId,nodeId:node.id,edgeId:null};renderCanvas();renderProperties();log('Element is already displayed on this diagram.','ok')}
function showExistingElement(elementId,position){const diagram=activeDiagram();if(!diagram)return log('No active diagram is available.','warn');const semantic=findElement(project,elementId),support=supportAction(semantic?.kind||'Unknown','element','present');if(!support.allowed)return log(support.message,'warn');const existing=findPresentation(project,elementId,diagram.id);if(existing)return revealPresentation(existing);if(diagram.diagramType==='Sequence Diagram'&&validLifelineRepresentation(project,elementId)){const participant=findElement(project,elementId),lifeline=defaultElement('Lifeline',diagram.contextId||diagram.ownerId);lifeline.name=participant.name;lifeline.representedElementId=participant.id;checkpoint();project.elements.push(lifeline);const shown=showElementOnDiagram(project,lifeline.id,diagram.id,position,{source:'containment-participant'});if(!shown.created){project.elements.pop();return log(shown.message,'warn')}selected={type:'element',id:lifeline.id,nodeId:shown.node.id,edgeId:null};commitLocal({type:'create-element',element:structuredClone(lifeline),diagramId:diagram.id,node:structuredClone(shown.node)},`Presented ${participant.name} as a Lifeline`);return}const verdict=canShowElementOnDiagram(project,elementId,diagram.id,{point:position});if(!verdict.valid)return log(verdict.message,'warn');checkpoint();const result=showElementOnDiagram(project,elementId,diagram.id,position,{source:'containment'});if(!result.created)return log(result.message,'warn');selected={type:'element',id:elementId,nodeId:result.node.id,edgeId:null};commitLocal({type:'add-presentation',diagramId:diagram.id,node:structuredClone(result.node)},`Displayed ${result.element.name} on ${diagram.name}`)}
const canvasWrap=$('canvasWrap');canvasWrap.addEventListener('pointermove',event=>{const rect=$('canvas').getBoundingClientRect();publishCurrentAwareness({cursor:{x:(event.clientX-rect.left)/zoom,y:(event.clientY-rect.top)/zoom}})});canvasWrap.addEventListener('pointerleave',()=>publishCurrentAwareness({cursor:null}));canvasWrap.addEventListener('scroll',()=>publishCurrentAwareness({viewport:{x:canvasWrap.scrollLeft/zoom,y:canvasWrap.scrollTop/zoom,width:canvasWrap.clientWidth/zoom,height:canvasWrap.clientHeight/zoom,zoom}}),{passive:true});
let containmentDragDepth=0;function draggedElementId(event){try{const payload=JSON.parse(event.dataTransfer.getData('application/x-sysml-containment+json')||'null');return payload?.semanticElementIds?.[0]||payload?.semanticElementId||draggedTreeElementId}catch{return draggedTreeElementId}}
canvasWrap.addEventListener('dragenter',event=>{const id=draggedElementId(event);if(!id)return;event.preventDefault();containmentDragDepth++;canvasWrap.classList.add('containment-drop-active')});
canvasWrap.addEventListener('dragover',event=>{const id=draggedElementId(event);if(!id)return;event.preventDefault();const point=diagramPointFromClient(event,$('canvas').getBoundingClientRect(),zoom),verdict=canShowElementOnDiagram(project,id,activeDiagram()?.id,{point});event.dataTransfer.dropEffect=verdict.valid?'copy':'none';canvasWrap.classList.toggle('drop-valid',verdict.valid);canvasWrap.classList.toggle('drop-invalid',!verdict.valid);const delta=edgeAutoPanDelta({x:event.clientX,y:event.clientY},canvasWrap.getBoundingClientRect());if(delta.x||delta.y)canvasWrap.scrollBy(delta.x,delta.y)});
canvasWrap.addEventListener('dragleave',event=>{if(--containmentDragDepth<=0||!canvasWrap.contains(event.relatedTarget)){containmentDragDepth=0;canvasWrap.classList.remove('containment-drop-active','drop-valid','drop-invalid')}});
canvasWrap.addEventListener('drop',event=>{event.preventDefault();event.stopPropagation();containmentDragDepth=0;canvasWrap.classList.remove('containment-drop-active','drop-valid','drop-invalid');const id=draggedElementId(event);draggedTreeElementId=null;if(!id)return;showExistingElement(id,diagramPointFromClient(event,$('canvas').getBoundingClientRect(),zoom))});
$('tree').addEventListener('dragover',event=>{const rect=$('tree').getBoundingClientRect(),margin=38;if(event.clientY<rect.top+margin)$('tree').scrollTop-=8;else if(event.clientY>rect.bottom-margin)$('tree').scrollTop+=8});

function setSelectMode(){tool=null;sourceId=null;sourceNodeId=null;openMessageAnchor=null;renderPalette();$('canvasWrap').classList.add('select-mode');log('Select mode.','ok')}
document.addEventListener('keydown',e=>{if(['ControlLeft','ControlRight','MetaLeft','MetaRight'].includes(e.code)&&!isEditingTarget(e.target))$('canvasWrap').classList.add('pan-ready');if(e.code==='Space'&&!isEditingTarget(e.target)){spacePan=true;$('canvasWrap').classList.add('pan-ready');e.preventDefault()}if(isEditingTarget(e.target))return;const mod=e.ctrlKey||e.metaKey;if(e.key==='Escape'){closeTreeContextMenu();setSelectMode();selectedNodeIds.clear();selected={type:null,id:null,nodeId:null,edgeId:null};renderCanvas();renderProperties();e.preventDefault()}else if(e.key==='F2'&&selected?.id){beginTreeRename(selected.id,selected.type);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='c'&&selected.type==='element'){copyTreeElement(selected.id);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='v'&&selected.type==='element'){pasteTreeElement(selected.id);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='d'&&selected.type==='element'){duplicateElement(selected.id);e.preventDefault()}else if(e.key==='Backspace'||e.key==='Delete'){if(selected?.id||selected?.nodeId||selected?.edgeId){deleteSelected();e.preventDefault()}}else if(mod&&e.key.toLowerCase()==='f'){e.preventDefault();$('searchBox').focus()}else if((e.altKey)&&e.key==='ArrowLeft'){navigationGoBack();e.preventDefault()}else if((e.altKey)&&e.key==='ArrowRight'){navigationGoForward();e.preventDefault()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selectedNodeIds.size){const step=e.shiftKey?10:1;const map={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,-step],ArrowDown:[0,step]};nudgeSelection(...map[e.key]);e.preventDefault()}});
document.addEventListener('keyup',e=>{if(e.code==='Space')spacePan=false;if(['Space','ControlLeft','ControlRight','MetaLeft','MetaRight'].includes(e.code))$('canvasWrap').classList.remove('pan-ready')});
const wrapEl=$('canvasWrap');
wrapEl.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();const rect=wrapEl.getBoundingClientRect(),cx=e.clientX-rect.left,cy=e.clientY-rect.top,worldX=(wrapEl.scrollLeft+cx)/zoom,worldY=(wrapEl.scrollTop+cy)/zoom,next=Math.max(.25,Math.min(3,zoom*Math.exp(-e.deltaY*.0015)));zoom=next;renderCanvas();wrapEl.scrollLeft=worldX*zoom-cx;wrapEl.scrollTop=worldY*zoom-cy},{passive:false});
let suppressPanClick=false;
wrapEl.addEventListener('pointerdown',e=>{if(!isDiagramPanGesture(e,{spacePan}))return;panState={pointerId:e.pointerId,x:e.clientX,y:e.clientY,left:wrapEl.scrollLeft,top:wrapEl.scrollTop,moved:false};wrapEl.classList.add('panning');wrapEl.setPointerCapture(e.pointerId);e.preventDefault();e.stopPropagation()},true);
wrapEl.addEventListener('pointermove',e=>{if(!panState||panState.pointerId!==e.pointerId)return;const next=diagramPanPosition(panState,e);wrapEl.scrollLeft=next.left;wrapEl.scrollTop=next.top;panState.moved||=next.moved});
function finishDiagramPan(e){if(!panState||e?.pointerId!==undefined&&panState.pointerId!==e.pointerId)return;suppressPanClick=panState.moved;panState=null;wrapEl.classList.remove('panning')}
wrapEl.addEventListener('pointerup',finishDiagramPan);wrapEl.addEventListener('pointercancel',finishDiagramPan);wrapEl.addEventListener('lostpointercapture',finishDiagramPan);wrapEl.addEventListener('click',e=>{if(!suppressPanClick)return;suppressPanClick=false;e.preventDefault();e.stopImmediatePropagation()},true);window.addEventListener('blur',()=>{spacePan=false;wrapEl.classList.remove('pan-ready');finishDiagramPan()});

